// Decide which CRM events deserve a Slack message and format them.
// Returning [] stops the flow for events we don't notify on.
const event = $input.first().json.body;
const d = event.data || {};
const via = d.source === 'voice' ? ' :microphone: _via voice_' : '';
const usd = (n) => '$' + Number(n || 0).toLocaleString('en-US');
let text = null;

switch (event.type) {
  case 'opportunity.stage_changed':
    if (d.to_stage === 'Won') text = `:tada: *Deal won!* ${d.title} with ${d.contact_name} (${usd(d.value)})${via}`;
    else if (d.to_stage === 'Lost') text = `:small_red_triangle_down: Deal lost: ${d.title} with ${d.contact_name}${via}`;
    else text = `:arrow_right: *${d.contact_name}* moved ${d.from_stage} → *${d.to_stage}* (${d.title}, ${usd(d.value)})${via}`;
    break;
  case 'lead.created':
    text = `:wave: New lead: *${d.name}*${d.company ? ' from ' + d.company : ''} (source: ${d.source})`;
    break;
  case 'task.created':
  case 'task.updated':
    if (d.source === 'voice') text = `:spiral_calendar_pad: Follow-up for *${d.contact_name}*: ${d.title} (due ${d.due_date})${via}`;
    break;
}

return text ? [{ json: { text } }] : [];
